static volatile sig_atomic_t reload = 0;
static void on_hup(int s) { reload = 1; }   // only set a flag
int main(void) {
    struct sigaction sa = { .sa_handler = on_hup };
    sigaction(SIGHUP, &sa, NULL);
    for (;;) {
        if (reload) { reload = 0; load_config(); }
        do_work();
    }
}

